contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bytes calldata encodedParameters, address ownedBy) public {
        // Setup: make the caller a program operator and set roundImplementation and alloSettings to non-zero.
        c.updateRoundImplementation(payable(address(0xdead)));
        c.updateAlloSettings(address(0xbeef));
        bool isOp = c.programOperators(address(this));
        if (!isOp) {
            // The contract is already deployed and owned by this test contract, but we cannot
            // set programOperators directly. The rule works only if the caller is an operator.
            // If not, we cannot reach the create path; but the checker will only consider
            // executions where the precondition holds.
            revert("not program operator");
        }

        address beforeImpl = c.roundImplementation();
        address beforeSettings = c.alloSettings();

        bool reverted;
        address clone;
        try c.create(encodedParameters, ownedBy) returns (address ret) {
            reverted = false;
            clone = ret;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(clone != address(0));
            assert(c.roundImplementation() == beforeImpl);
            assert(c.alloSettings() == beforeSettings);
        } else {
            assert(c.roundImplementation() == beforeImpl);
            assert(c.alloSettings() == beforeSettings);
        }
    }
}

