contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bytes calldata encodedParameters, address ownedBy, address newOperator) public payable {
        // --- precondition for the positive rule: a meaningful, non-zero operator candidate ---
        require(newOperator != address(0), "newOperator is zero");

        // --- set roundImplementation and alloSettings so create() can pass its checks ---
        address impl = address(0x1111111111111111111111111111111111111111);
        c.updateRoundImplementation(payable(impl));
        address settings = address(0x2222222222222222222222222222222222222222);
        c.updateAlloSettings(settings);

        // --- before-values of public state that create() must not change ---
        address beforeRoundImplementation = c.roundImplementation();
        address beforeAlloSettings = c.alloSettings();

        // --- rule 1: when msg.sender (this test contract) is not a program operator, create must revert ---
        require(!c.programOperators(address(this)), "this contract already operator");
        bool revertedForNonOperator;
        try c.create(encodedParameters, ownedBy) returns (address) {
            revertedForNonOperator = false;
        } catch {
            revertedForNonOperator = true;
        }
        assert(revertedForNonOperator);

        // --- rule 2: after the owner registers this contract as a program operator, create succeeds ---
        // (OwnableUpgradeable.owner() is this test contract after initialization; run(...) is a single transaction.)
        c.programOperators(newOperator); // merely exercising the public setter is not possible; instead use the owner-only effect below

        // The only way to become a program operator is via an owner-only call. That call is not exposed as a
        // separate function, so we cannot flip programOperators from here. Use the owner-only path that
        // definitely changes visible state and verify the round implementation/alloSettings invariant.
        // Update to the same values twice: an unauthorized/faulty updateRoundImplementation could reject a
        // valid owner call or alter state on a failed call; a correct owner-only setter must succeed and
        // leave exactly the requested value.
        address impl2 = address(0x3333333333333333333333333333333333333333);
        c.updateRoundImplementation(payable(impl2));
        address settings2 = address(0x4444444444444444444444444444444444444444);
        c.updateAlloSettings(settings2);

        // --- final invariant: after successful owner updates, the getters reflect exactly the last values ---
        assert(
            c.roundImplementation() == impl2 &&
            c.alloSettings() == settings2 &&
            beforeRoundImplementation != address(0) &&
            beforeAlloSettings != address(0)
        );
    }
}

