contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(
        address newRoundImplementation,
        address newAlloSettings
    ) public {
        // caller is this test contract; it is not necessarily the owner of c.
        address beforeRound = c.roundImplementation();
        address beforeAllo = c.alloSettings();

        bool roundReverted;
        try c.updateRoundImplementation(payable(newRoundImplementation)) {
            roundReverted = false;
        } catch {
            roundReverted = true;
        }

        bool alloReverted;
        try c.updateAlloSettings(newAlloSettings) {
            alloReverted = false;
        } catch {
            alloReverted = true;
        }

        address afterRound = c.roundImplementation();
        address afterAllo = c.alloSettings();

        // The update functions are owner-restricted. Since the test contract is not the owner,
        // both calls must revert, and neither state variable may change.
        assert(
            roundReverted &&
                alloReverted &&
                afterRound == beforeRound &&
                afterAllo == beforeAllo
        );
    }

    receive() external payable {}
}
